  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val TemperatureEvidenceQualification_supervisionProcess_temperatureQualification_id = Arch.VehicleTemperatureHealthSupervisorSystem_Instance_supervisionProcess_temperatureQualification.id
    val MaintenanceEvidenceQualification_supervisionProcess_maintenanceQualification_id = Arch.VehicleTemperatureHealthSupervisorSystem_Instance_supervisionProcess_maintenanceQualification.id
    val RecoveryApplicability_supervisionProcess_recoveryApplicability_id = Arch.VehicleTemperatureHealthSupervisorSystem_Instance_supervisionProcess_recoveryApplicability.id
    val HealthModeArbitration_supervisionProcess_healthModeArbitration_id = Arch.VehicleTemperatureHealthSupervisorSystem_Instance_supervisionProcess_healthModeArbitration.id
    val BoundaryOutcomeDerivation_supervisionProcess_boundaryOutcomeDerivation_id = Arch.VehicleTemperatureHealthSupervisorSystem_Instance_supervisionProcess_boundaryOutcomeDerivation.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case TemperatureEvidenceQualification_supervisionProcess_temperatureQualification_id =>
          val prefix = "TemperatureEvidenceQualification_supervisionProcess_temperatureQualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Vehicle_Temperature_Health_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Vehicle_Temperature_Health_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Vehicle_Temperature_Health_Supervisor._
                |
                |class ${suiteName} extends TemperatureEvidenceQualification_supervisionProcess_temperatureQualification_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case MaintenanceEvidenceQualification_supervisionProcess_maintenanceQualification_id =>
          val prefix = "MaintenanceEvidenceQualification_supervisionProcess_maintenanceQualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Vehicle_Temperature_Health_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Vehicle_Temperature_Health_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Vehicle_Temperature_Health_Supervisor._
                |
                |class ${suiteName} extends MaintenanceEvidenceQualification_supervisionProcess_maintenanceQualification_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case RecoveryApplicability_supervisionProcess_recoveryApplicability_id =>
          val prefix = "RecoveryApplicability_supervisionProcess_recoveryApplicability_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Vehicle_Temperature_Health_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Vehicle_Temperature_Health_Supervisor
                |
