          println(s"Wrote: ${filename.toUri}")
        case HealthModeArbitration_supervisionProcess_healthModeArbitration_id =>
          val prefix = "HealthModeArbitration_supervisionProcess_healthModeArbitration_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Vehicle_Temperature_Health_Supervisor")
